import Darwin
import Foundation

/// Everything `session enable` asks of the root helper.
public struct ProvisioningRequest: Sendable {
    public var name: String
    public var fullName: String
    /// The account's login password. Generated by the app for a new account and kept in the
    /// console user's keychain; for an existing account, the one it already has.
    public var password: String
    /// The public half of the key the console-side daemon reaches the account with. Installed
    /// behind a forced command, so it can run `<cli> session remote` and nothing else.
    public var authorizedKey: String
    /// The Rocuronium.app the account's LaunchAgent and forced command point into.
    public var appPath: String

    public init(name: String, fullName: String, password: String, authorizedKey: String, appPath: String) {
        self.name = name
        self.fullName = fullName
        self.password = password
        self.authorizedKey = authorizedKey
        self.appPath = appPath
    }

    var cliPath: String { appPath + "/Contents/Resources/rocuronium" }
    var appExecutable: String { appPath + "/Contents/MacOS/Rocuronium" }
}

/// How the provisioner reaches the system, so a test can read every argv it would run.
public protocol CommandRunner: Sendable {
    func run(_ executable: String, _ arguments: [String], input: Data?) -> CommandResult
    func answeringPrompt(_ prompt: String, with secret: String, argv: [String]) -> CommandResult
}

public struct LiveCommandRunner: CommandRunner {
    public init() {}

    public func run(_ executable: String, _ arguments: [String], input: Data?) -> CommandResult {
        Shell.run(executable, arguments, input: input)
    }

    public func answeringPrompt(_ prompt: String, with secret: String, argv: [String]) -> CommandResult {
        Shell.answeringPrompt(prompt, with: secret, argv: argv)
    }
}

/// Creates (or refreshes) an agent account and strips it to something worth running: the Swift
/// form of `Scripts/provision-agent-account.sh`, run as root by the session helper.
///
/// What "stripped" means and why each piece is here:
/// - **Onboarding** is skipped by pre-seeding the keys Setup Assistant writes when a human
///   clicks through it; the list is the one in the Setup Assistant binary, and the values were
///   read back from an account that had been through the flow.
/// - **The background suite** (Spotlight, Siri, proactive/duet, Shortcuts) is what an idle
///   session spends its ~3.1 W on. Preferences only reduce how much work those daemons choose
///   to do — SIP forbids stopping them — which measured as ~2.4 W.
/// - **A still black wallpaper**, because the default aerial's extension held 241 MB and
///   rendered continuously for a desktop nobody watches.
///
/// Every write into the account's home runs *as the account* (`sudo -u`): another user's
/// `~/Library` is TCC-protected even against root, while the account writing its own files is
/// ordinary. That is why provisioning needs root but not Full Disk Access.
public struct Provisioner: Sendable {
    let runner: any CommandRunner
    let system: any AccountSystem

    public init(runner: any CommandRunner = LiveCommandRunner(), system: any AccountSystem = LiveAccountSystem()) {
        self.runner = runner
        self.system = system
    }

    public enum Outcome: Equatable, Sendable {
        case provisioned(uid: uid_t, created: Bool, log: [String])
        case refused(String, log: [String])
    }

    /// - Parameter protecting: the requesting user's uid, which may never be provisioned over.
    public func run(_ request: ProvisioningRequest, protecting: uid_t?) -> Outcome {
        var log: [String] = []
        let created: Bool
        switch Provisioning.gate(name: request.name, system: system, protecting: protecting) {
        case let .refused(reason):
            return .refused(reason, log: log)
        case .new:
            guard request.password.count >= 12 else {
                return .refused("a new agent account needs a password of at least 12 characters", log: log)
            }
            // Never -admin: the two service ACLs below are the whole access model, and an
            // admin account would bypass them while gaining far more than an agent needs.
            let made = runner.answeringPrompt(
                "User password:", with: request.password,
                argv: ["/usr/sbin/sysadminctl", "-addUser", request.name, "-fullName", request.fullName, "-password", "-"],
            )
            guard system.uid(of: request.name) != nil else {
                return .refused("account creation failed: \(made.output)", log: log)
            }
            log.append("created \(request.name) (standard user)")
            created = true
        case .existing:
            log.append("\(request.name) exists and has no running session")
            created = false
        }
        // A record with an unusable password cannot be repaired here — changing an existing
        // account's password demands a SecureToken unlock — so it is caught now rather than
        // stored in the keychain to fail at the first login.
        let verified = runner.answeringPrompt("Password:", with: request.password, argv: ["/usr/bin/dscl", ".", "-authonly", request.name])
        guard verified.succeeded else {
            return .refused(
                created
                    ? "created \(request.name), but password verification failed (exit \(verified.status))"
                    : "password verification for '\(request.name)' failed (exit \(verified.status))",
                log: log,
            )
        }
        log.append("credential verified")
        guard let uid = system.uid(of: request.name) else { return .refused("\(request.name) vanished mid-provisioning", log: log) }
        let home = homeDirectory(of: request.name)
        if !FileManager.default.fileExists(atPath: home) {
            runner.run("/usr/sbin/createhomedir", ["-c", "-u", request.name], input: nil)
        }

        // Recorded before anything else is written, so a half-provisioned account can still be
        // removed by the helper that started it.
        system.register(request.name)
        enableServices(for: request.name, log: &log)
        writePreferences(for: request.name, log: &log)
        installFiles(request, home: home, log: &log)
        return .provisioned(uid: uid, created: created, log: log)
    }

    // MARK: - Steps

    /// Both ACLs, or authentication fails in a way that looks exactly like a wrong password:
    /// macOS checks the password first and the service ACL second.
    private func enableServices(for name: String, log: inout [String]) {
        for group in ["com.apple.access_screensharing", "com.apple.access_ssh"] {
            runner.run("/usr/sbin/dseditgroup", ["-o", "edit", "-a", name, "-t", "user", group], input: nil)
        }
        log.append("added to com.apple.access_screensharing and com.apple.access_ssh")
        // `enable` + `bootstrap` turn a service on without the kickstart -k that would drop
        // any viewer the human already has connected. A bootstrap of a loaded service fails
        // harmlessly.
        for (label, plist) in [
            ("com.apple.screensharing", "/System/Library/LaunchDaemons/com.apple.screensharing.plist"),
            ("com.openssh.sshd", "/System/Library/LaunchDaemons/ssh.plist"),
        ] {
            runner.run("/bin/launchctl", ["enable", "system/\(label)"], input: nil)
            runner.run("/bin/launchctl", ["bootstrap", "system", plist], input: nil)
        }
        log.append("Screen Sharing and Remote Login enabled")
    }

    private func writePreferences(for name: String, log: inout [String]) {
        let version = runner.run("/usr/bin/sw_vers", ["-productVersion"], input: nil).output.trimmingCharacters(in: .whitespacesAndNewlines)
        let build = runner.run("/usr/bin/sw_vers", ["-buildVersion"], input: nil).output.trimmingCharacters(in: .whitespacesAndNewlines)
        for write in Self.preferenceWrites(osVersion: version, build: build) {
            runner.run("/usr/bin/sudo", ["-u", name, "/usr/bin/defaults"] + write, input: nil)
        }
        log.append("onboarding skipped, Siri and suggestions off, desktop stilled, no screen saver or idle lock")
    }

    /// The `defaults` arguments, as the account. Every `DidSee*` key Setup Assistant knows is
    /// marked seen: anything left unset is a pane the first login stops on.
    static func preferenceWrites(osVersion: String, build: String) -> [[String]] {
        var writes: [[String]] = []
        let setup = "com.apple.SetupAssistant"
        for key in [
            "DidSeeAccessibility", "DidSeeActivationLock", "DidSeeAppearanceSetup", "DidSeeApplePaySetup",
            "DidSeeAppStore", "DidSeeCloudSetup", "DidSeeiCloudLoginForStorageServices", "DidSeeLockdownMode",
            "DidSeePrivacy", "DidSeeScreenTime", "DidSeeSiriSetup", "DidSeeSyncSetup", "DidSeeSyncSetup2",
            "DidSeeTermsOfAddress", "DidSeeTouchIDSetup",
        ] {
            writes.append(["write", setup, key, "-bool", "true"])
        }
        for key in [
            "LastSeenAgeRangeSelectionProductVersion", "LastSeenCloudProductVersion",
            "LastSeenDiagnosticsProductVersion", "LastSeeniCloudStorageServicesProductVersion",
            "LastSeenIntelligenceProductVersion", "LastSeenSiriProductVersion", "LastSeenSyncProductVersion",
        ] {
            writes.append(["write", setup, key, "-string", osVersion])
        }
        writes += [
            ["write", setup, "LastSeenBuddyBuildVersion", "-string", build],
            ["write", setup, "MiniBuddyShouldLaunchToResumeSetup", "-bool", "false"],
            ["write", setup, "SkipFirstLoginOptimization", "-bool", "true"],
            ["write", setup, "SkipWallpaperAnimation", "-bool", "true"],
            ["write", "com.apple.assistant.support", "Assistant Enabled", "-bool", "false"],
            ["write", "com.apple.Siri", "StatusMenuVisible", "-bool", "false"],
            ["write", "com.apple.Siri", "VoiceTriggerUserEnabled", "-bool", "false"],
            ["write", "com.apple.Siri", "TypeToSiriEnabled", "-bool", "false"],
            ["write", "com.apple.lookup.shared", "LookupSuggestionsDisabled", "-bool", "true"],
            ["write", "com.apple.suggestions", "SuggestionsAppLibraryEnabled", "-bool", "false"],
            ["write", "com.apple.Spotlight", "showedFTE", "-bool", "true"],
            ["write", "com.apple.dock", "autohide", "-bool", "true"],
            ["write", "com.apple.dock", "launchanim", "-bool", "false"],
            ["write", "com.apple.dock", "expose-animation-duration", "-float", "0"],
            ["write", "com.apple.dock", "mineffect", "-string", "scale"],
            ["write", "com.apple.finder", "DisableAllAnimations", "-bool", "true"],
            ["write", "com.apple.finder", "CreateDesktop", "-bool", "false"],
            ["write", "NSGlobalDomain", "NSAutomaticWindowAnimationsEnabled", "-bool", "false"],
            ["write", "NSGlobalDomain", "NSScrollAnimationEnabled", "-bool", "false"],
            // The session has no seat and nobody watching: a screen saver renders for an audience
            // of zero, and an idle lock would curtain the session out from under the agent.
            ["-currentHost", "write", "com.apple.screensaver", "idleTime", "-int", "0"],
            ["write", "com.apple.screensaver", "askForPassword", "-bool", "false"],
        ]
        return writes
    }

    private func installFiles(_ request: ProvisioningRequest, home: String, log: inout [String]) {
        let name = request.name
        // "No wallpaper index" resolves to the system default, which is the aerial, so a still
        // choice is written in explicitly.
        let wallpaperStore = home + "/Library/Application Support/com.apple.wallpaper/Store"
        writeAsAccount(name, directory: wallpaperStore, file: "Index.plist", contents: Templates.blackWallpaperIndex, log: &log, what: "solid black wallpaper")

        let agents = home + "/Library/LaunchAgents"
        writeAsAccount(name, directory: agents, file: "glass.kagerou.rocuronium.plist",
                       contents: Data(Templates.launchAgent(appExecutable: request.appExecutable).utf8),
                       log: &log, what: "Rocuronium LaunchAgent (loads at the session's login)")

        let ssh = home + "/.ssh"
        let existing = runner.run("/usr/bin/sudo", ["-u", name, "/bin/cat", ssh + "/authorized_keys"], input: nil)
        let kept = existing.succeeded ? existing.output : ""
        let keys = Templates.authorizedKeys(existing: kept, publicKey: request.authorizedKey, cliPath: request.cliPath)
        writeAsAccount(name, directory: ssh, file: "authorized_keys", contents: Data(keys.utf8), log: &log, what: "Rocuronium's SSH key, restricted to `session remote`")
        runner.run("/usr/bin/sudo", ["-u", name, "/bin/chmod", "700", ssh], input: nil)
        runner.run("/usr/bin/sudo", ["-u", name, "/bin/chmod", "600", ssh + "/authorized_keys"], input: nil)
    }

    private func writeAsAccount(_ name: String, directory: String, file: String, contents: Data, log: inout [String], what: String) {
        runner.run("/usr/bin/sudo", ["-u", name, "/bin/mkdir", "-p", directory], input: nil)
        let wrote = runner.run("/usr/bin/sudo", ["-u", name, "/usr/bin/tee", directory + "/" + file], input: contents)
        log.append(wrote.succeeded ? what : "could not write \(what): \(wrote.output)")
    }

    private func homeDirectory(of name: String) -> String {
        guard let entry = getpwnam(name), let directory = entry.pointee.pw_dir else { return "/Users/\(name)" }
        return String(cString: directory)
    }
}

/// The files provisioning installs, as data rather than as paths into a bundle a root helper
/// would have to trust.
public enum Templates {
    /// A wallpaper store index whose single choice is provider `com.apple.wallpaper.choice.color`
    /// with `{type: systemColor, systemColor: {black: {}}}` — captured from a session where a
    /// still color was chosen by hand, with nothing machine- or account-specific in it. Same
    /// bytes as `Scripts/agent-wallpaper-black.plist`.
    public static let blackWallpaperIndex = Data(base64Encoded: """
        YnBsaXN0MDDUAQIDBAUcIiNfEBRBbGxTcGFjZXNBbmREaXNwbGF5c11TeXN0ZW1EZWZhdWx0VlNwYWNlc1hEaXNwbGF5c9IGBwgJ\
        VFR5cGVWTGlua2VkVmxpbmtlZNMKCwwNDQ5XTGFzdFNldFdMYXN0VXNlV0NvbnRlbnQzQcgg5Bry7LfTDxAREhobV0Nob2ljZXNX\
        U2h1ZmZsZV8QE0VuY29kZWRPcHRpb25WYWx1ZXOhE9MUFRYXGBlYUHJvdmlkZXJVRmlsZXNdQ29uZmlndXJhdGlvbl8QIGNvbS5h\
        cHBsZS53YWxscGFwZXIuY2hvaWNlLmNvbG9yoE8QTmJwbGlzdDAw0gECAgNUdHlwZVtzeXN0ZW1Db2xvctEEBVVibGFja9AIDRIe\
        IScAAAAAAAABAQAAAAAAAAAGAAAAAAAAAAAAAAAAAAAAKFUkbnVsbE8QNmJwbGlzdDAw0QECVnZhbHVlc9AICxIAAAAAAAABAQAA\
        AAAAAAADAAAAAAAAAAAAAAAAAAAAE9IGBwgd0woLDA0NHtMPEBEfGhuhINMUFRYXIRmg0NAACAARACgANgA9AEYASwBQAFcAXgBl\
        AG0AdQB9AIYAjQCVAJ0AswC1ALwAxQDLANkA/AD9AU4BVAGNAZIBmQGgAaIBqQGqAasAAAAAAAACAQAAAAAAAAAkAAAAAAAAAAAA\
        AAAAAAABrA==
        """)!

    /// The marker that identifies rocuronium's line in `authorized_keys`, so re-provisioning
    /// replaces it instead of piling up keys.
    public static let keyComment = "rocuronium-agent-session"

    /// `restrict` turns off forwarding, the pty, and the rest; `command=` makes sshd ignore what
    /// the client asked to run. Other keys in the file are kept as they were.
    public static func authorizedKeys(existing: String, publicKey: String, cliPath: String) -> String {
        let fields = publicKey.split(separator: " ")
        let key = fields.prefix(2).joined(separator: " ")
        var lines = existing.split(separator: "\n", omittingEmptySubsequences: true).map(String.init)
        lines.removeAll { $0.hasSuffix(" " + keyComment) }
        lines.append(#"restrict,command="\#(cliPath) session remote" \#(key) \#(keyComment)"#)
        return lines.joined(separator: "\n") + "\n"
    }

    /// The same LaunchAgent the console install uses (`Scripts/glass.kagerou.rocuronium.plist`):
    /// `RunAtLoad`, and `KeepAlive` on unsuccessful exit only, so Quit stays quit.
    public static func launchAgent(appExecutable: String) -> String {
        """
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0">
        <dict>
        \t<key>Label</key>
        \t<string>glass.kagerou.rocuronium</string>
        \t<key>Program</key>
        \t<string>\(appExecutable)</string>
        \t<key>RunAtLoad</key>
        \t<true/>
        \t<key>KeepAlive</key>
        \t<dict>
        \t\t<key>SuccessfulExit</key>
        \t\t<false/>
        \t</dict>
        \t<key>ProcessType</key>
        \t<string>Interactive</string>
        \t<key>AssociatedBundleIdentifiers</key>
        \t<string>glass.kagerou.rocuronium</string>
        </dict>
        </plist>

        """
    }
}
